import{_ as t,c as n,o,ag as i}from"./chunks/framework.CoPVQkzc.js";const h=JSON.parse('{"title":"Debugger","description":"Step-through debugging of channels","frontmatter":{"title":"Debugger","description":"Step-through debugging of channels"},"headers":[],"relativePath":"engine/debugger.md","filePath":"engine/debugger.md","lastUpdated":1788476353000}'),r={name:"engine/debugger.md"};function a(s,e,l,u,c,d){return o(),n("div",null,e[0]||(e[0]=[i('<h1 id="debugger" tabindex="-1">Debugger <a class="header-anchor" href="#debugger" aria-label="Permalink to &quot;Debugger&quot;">​</a></h1><p>The OIE Debugger allows you to step through channel JavaScript execution interactively, inspecting variable state at each point in your scripts.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Debugger is built on the Rhino JavaScript engine&#39;s debugging API. When a channel is deployed in debug mode, a standalone debugger window opens where you can:</p><ul><li>Set line-level breakpoints in JavaScript source</li><li>Step through execution one line at a time</li><li>Inspect <code>this</code> and local scope variables at each breakpoint</li><li>Evaluate expressions and set watches</li><li>Control execution flow (break, resume, step into/over/out)</li></ul><h2 id="deploying-in-debug-mode" tabindex="-1">Deploying in debug mode <a class="header-anchor" href="#deploying-in-debug-mode" aria-label="Permalink to &quot;Deploying in debug mode&quot;">​</a></h2><ol><li>Select the channel in the <strong>Channels</strong> view or open it in the channel editor</li><li>Click <strong>Debug Channel</strong> in the channel tasks panel</li><li>A <strong>Debug Channel</strong> dialog appears with checkboxes to select which scripts to debug: <ul><li>Deploy/Undeploy/Preprocessor/Postprocessor scripts</li><li>Attachment/Batch scripts</li><li>Source connector scripts</li><li>Source filter/transformer</li><li>Destination filter/transformer</li><li>Destination connector scripts</li><li>Destination response transformer</li></ul></li><li>Select the desired script types and click <strong>OK</strong></li><li>The channel deploys and the debugger window opens</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Debug mode affects performance. Only use it during development, not in production.</p></div><h2 id="debugger-window" tabindex="-1">Debugger window <a class="header-anchor" href="#debugger-window" aria-label="Permalink to &quot;Debugger window&quot;">​</a></h2><p>The Debugger opens as a separate Rhino JavaScript Debugger window with two main areas: source windows for viewing code, and a context panel for inspecting variables.</p><h3 id="source-windows" tabindex="-1">Source windows <a class="header-anchor" href="#source-windows" aria-label="Permalink to &quot;Source windows&quot;">​</a></h3><ul><li>Display the JavaScript source for the scripts being debugged</li><li>A yellow arrow in the gutter indicates the currently executing line</li><li>Line numbers and breakpoint markers appear in the left gutter</li></ul><h3 id="debug-controls" tabindex="-1">Debug controls <a class="header-anchor" href="#debug-controls" aria-label="Permalink to &quot;Debug controls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><strong>Break</strong></td><td>Pause</td><td>Pause execution at the current point</td></tr><tr><td><strong>Go</strong></td><td>F5</td><td>Resume execution until the next breakpoint</td></tr><tr><td><strong>Step Into</strong></td><td>F11</td><td>Step into the current function call</td></tr><tr><td><strong>Step Over</strong></td><td>F7</td><td>Execute the current line without entering sub-functions</td></tr><tr><td><strong>Step Out</strong></td><td>F8</td><td>Execute until the current function returns</td></tr></tbody></table><h3 id="context-panel" tabindex="-1">Context panel <a class="header-anchor" href="#context-panel" aria-label="Permalink to &quot;Context panel&quot;">​</a></h3><p>The context panel has a <strong>Context</strong> dropdown to select the current stack frame, and two sets of tabs:</p><p><strong>Variable tabs:</strong></p><ul><li><strong>this</strong>. Displays properties of the current <code>this</code> object in a tree table</li><li><strong>Locals</strong>. Displays local variables in the current scope</li></ul><p><strong>Evaluation tabs:</strong></p><ul><li><strong>Watch</strong>. Shows watched expressions and their values</li><li><strong>Evaluate</strong>. A text area where you can type and execute JavaScript expressions during a breakpoint</li></ul><h2 id="debugger-menus" tabindex="-1">Debugger menus <a class="header-anchor" href="#debugger-menus" aria-label="Permalink to &quot;Debugger menus&quot;">​</a></h2><h3 id="file-menu" tabindex="-1">File menu <a class="header-anchor" href="#file-menu" aria-label="Permalink to &quot;File menu&quot;">​</a></h3><ul><li><strong>Open</strong>. Open a JavaScript source file</li><li><strong>Run</strong>. Load and run a JavaScript file</li><li><strong>Exit</strong>. Close the debugger</li></ul><h3 id="edit-menu" tabindex="-1">Edit menu <a class="header-anchor" href="#edit-menu" aria-label="Permalink to &quot;Edit menu&quot;">​</a></h3><ul><li><strong>Cut</strong>, <strong>Copy</strong>, <strong>Paste</strong>. Standard clipboard operations</li><li><strong>Go to function</strong>. Jump to a function definition</li><li><strong>Go to line</strong>. Jump to a specific line number (Ctrl+L)</li></ul><h3 id="debug-menu" tabindex="-1">Debug menu <a class="header-anchor" href="#debug-menu" aria-label="Permalink to &quot;Debug menu&quot;">​</a></h3><ul><li><strong>Break</strong>, <strong>Go</strong>, <strong>Step Into</strong>, <strong>Step Over</strong>, <strong>Step Out</strong>. Execution control</li><li><strong>Break on Exceptions</strong>. Pause when an exception is thrown</li><li><strong>Break on Function Enter</strong>. Pause at each function entry</li><li><strong>Break on Function Return</strong>. Pause at each function return</li></ul><h3 id="window-menu" tabindex="-1">Window menu <a class="header-anchor" href="#window-menu" aria-label="Permalink to &quot;Window menu&quot;">​</a></h3><ul><li><strong>Cascade</strong>. Cascade open source windows</li><li><strong>Tile</strong>. Tile open source windows</li><li><strong>Console</strong>. Show the console window</li><li>Lists open source file windows for quick navigation</li></ul><h2 id="setting-breakpoints" tabindex="-1">Setting breakpoints <a class="header-anchor" href="#setting-breakpoints" aria-label="Permalink to &quot;Setting breakpoints&quot;">​</a></h2><ol><li>In a source window, click in the left gutter next to a line number</li><li>A breakpoint indicator appears on that line</li><li>When execution reaches that line, the debugger pauses</li><li>Inspect variables in the context panel and use step controls to continue</li></ol><p>You can also use the right-click context menu in source windows to set or clear breakpoints.</p>',32)]))}const p=t(r,[["render",a]]);export{h as __pageData,p as default};
